import{_ as t,o as a,c as r,a6 as s}from"./chunks/framework.BHBQfcoO.js";const p=JSON.parse('{"title":"Internals","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/internals/index.md","filePath":"architecture/internals/index.md"}'),n={name:"architecture/internals/index.md"};function i(o,e,d,c,l,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="internals" tabindex="-1">Internals <a class="header-anchor" href="#internals" aria-label="Permalink to &quot;Internals&quot;">​</a></h1><p>This section documents lower-level implementation details that underpin the subsystems above. You rarely need to touch this code directly, but understanding it is valuable when debugging unexpected rendering behaviour, contributing new visual effects, or tracing data through the pipeline.</p><hr><h2 id="pages-in-this-section" tabindex="-1">Pages in This Section <a class="header-anchor" href="#pages-in-this-section" aria-label="Permalink to &quot;Pages in This Section&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="#background-animation-system">Background Animation System</a></td><td>Canvas2D rendering pipeline for animated card backgrounds</td></tr><tr><td><a href="#datasource-buffer-structure">DataSource Buffers</a></td><td>Internal buffer and processor-output data shape</td></tr><tr><td><a href="#ha-entity-display-utility">HA Entity Display</a></td><td>Locale-aware entity value formatting</td></tr><tr><td><a href="#ha-services-implementation-notes">HA Services: Implementation Notes</a></td><td>Backend service architecture and server-push channel</td></tr><tr><td><a href="#shape-texture-system">Shape Texture System</a></td><td>SVG-native declarative texture effects inside card shapes</td></tr><tr><td><a href="#persistent-storage">Persistent Storage</a></td><td>HA-backed key/value store for user and layout state</td></tr></tbody></table><hr><h2 id="background-animation-system" tabindex="-1">Background Animation System <a class="header-anchor" href="#background-animation-system" aria-label="Permalink to &quot;Background Animation System&quot;">​</a></h2><p><a href="./background-animation-system.html">Full reference →</a></p><p>Canvas2D rendering architecture for animated card backgrounds. An effect stack system applies modular preset effects (particles, warp, scan lines, noise, etc.) and an <code>AnimationPerformanceMonitor</code> degrades quality automatically on low-end devices.</p><p>Consult this when implementing new canvas-based visual effects, configuring background animations on cards, or investigating performance degradation.</p><hr><h2 id="datasource-buffer-structure" tabindex="-1">DataSource Buffer Structure <a class="header-anchor" href="#datasource-buffer-structure" aria-label="Permalink to &quot;DataSource Buffer Structure&quot;">​</a></h2><p><a href="./datasource-buffers.html">Full reference →</a></p><p>Documents the internal shape of datasource data objects: the main <code>v</code> buffer holding raw entity values, and named processor buffers holding outputs from unit conversion, moving averages, rate calculations, and other pipeline stages.</p><p>Consult this when referencing datasource values in templates (<code>{ds:source.buffer}</code>), configuring processors, or accessing buffers directly via <code>DataSourceManager</code>.</p><hr><h2 id="ha-entity-display-utility" tabindex="-1">HA Entity Display Utility <a class="header-anchor" href="#ha-entity-display-utility" aria-label="Permalink to &quot;HA Entity Display Utility&quot;">​</a></h2><p><a href="./ha-entity-display.html">Full reference →</a></p><p>Centralised utility (<code>src/utils/ha-entity-display.js</code>) for i18n/locale-aware formatting of Home Assistant entity values. Delegates to the stable <code>hass.format*</code> API family and provides graceful fallbacks. This is the single source of truth for all HA text formatting in LCARdS.</p><p>Consult this when displaying entity values, units, or state strings in cards to ensure consistent formatting and translation support.</p><hr><h2 id="ha-services-implementation-notes" tabindex="-1">HA Services: Implementation Notes <a class="header-anchor" href="#ha-services-implementation-notes" aria-label="Permalink to &quot;HA Services: Implementation Notes&quot;">​</a></h2><p><a href="./ha-services.html">Full reference →</a></p><p>Documents the LCARdS backend service architecture: alert mode management, frontend control directives, screen effects, sound, portal overlays, and the server-push channel that broadcasts events (reload, log level changes, effect/portal triggers) to connected browser tabs, with optional per-device/per-user targeting.</p><p>Consult this when understanding how HA service calls interact with the integration lifecycle, or when implementing features that need the push channel.</p><hr><h2 id="shape-texture-system" tabindex="-1">Shape Texture System <a class="header-anchor" href="#shape-texture-system" aria-label="Permalink to &quot;Shape Texture System&quot;">​</a></h2><p><a href="./shape-texture-system.html">Full reference →</a></p><p>SVG-native texture system that renders declarative effects (grid, plasma, fluid, level fills, etc.) inside button and elbow shape boundaries. Complements the canvas background system but operates entirely in SVG, driving color and template evaluation through the same pipeline as the rest of the card.</p><p>Consult this when configuring animated textures on cards, adding new SVG-based preset effects, or tracing texture color resolution.</p><hr><h2 id="persistent-storage" tabindex="-1">Persistent Storage <a class="header-anchor" href="#persistent-storage" aria-label="Permalink to &quot;Persistent Storage&quot;">​</a></h2><p><a href="./storage.html">Full reference →</a></p><p>Key/value store backed by Home Assistant&#39;s storage API (written to <code>.storage/lcards</code>), exposed over WebSocket as read/write/delete commands. Values survive HA restarts. Used by scoped settings, layout state, and any feature that needs cross-session persistence.</p><p>Consult this when implementing user preferences or dashboard state that must survive page reloads and HA restarts.</p>',35)])])}const f=t(n,[["render",i]]);export{p as __pageData,f as default};
